<p class="eyebrow"><?= $e($t('YOUR STEWARD ACCOUNT')) ?></p><h1><?= $e($actor['display_name']) ?></h1><p><?= $e($actor['username']) ?> · <?= $e($actor['email']) ?></p><section class="card"><h2><?= $e($t('Your communities')) ?></h2><?php if ($actor['is_owner']): ?><p><?= $e($t('Site owner · access to all collections and team settings.')) ?></p><?php endif ?><?php foreach ($communities as $community): ?><p><?= $e($community['name']) ?> · <?= $e($community['role']??$t('Site owner')) ?></p><?php endforeach ?><p><?= $e($t('Stewards maintain records and decide requests. Reviewers can read private records. Community admins also manage their own community teams. The site owner manages all accounts and memberships. Roles record delegated access; they do not verify cultural authority.')) ?></p></section><section class="card"><h2><?= $e($t('Change your password')) ?></h2><p><?= $e($t('Use 12–72 bytes. Changing your password signs out all sessions. Sign in again with the new password.')) ?></p><form data-api="/api/account/password" data-reload><label><?= $e($t('Current password')) ?><input type="password" name="currentPassword" required autocomplete="current-password"></label><label><?= $e($t('New password')) ?><input type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><button class="button"><?= $e($t('Change password and sign out')) ?></button><p class="form-message" role="status"></p></form></section>
